67	router.put("/:taskId", async (req, res): Promise<void> => {
68	  const params = UpdateOfficeTaskParams.safeParse({ taskId: Number(req.params.taskId) });
69	  if (!params.success) {
70	    res.status(400).json({ error: "Invalid taskId" });
71	    return;
72	  }
73	
74	  const body = { ...req.body };
75	  if (body.dueDate === "") body.dueDate = null;
76	  if (body.category === "") body.category = null;
77	  if (body.notes === "") body.notes = null;
78	
79	  const parsed = UpdateOfficeTaskBody.safeParse(body);
80	  if (!parsed.success) {
81	    res.status(400).json({ error: parsed.error.message });
82	    return;
83	  }
84	
85	  const existing = await db.select().from(officeTasksTable).where(eq(officeTasksTable.id, params.data.taskId));
86	  if (existing.length === 0) {
87	    res.status(404).json({ error: "Office task not found" });
88	    return;
89	  }
90	
91	  const updates: Record<string, unknown> = { ...parsed.data };
92	
93	  // Sync completed <-> status consistency
94	  if (parsed.data.completed === true) {
95	    updates.completedAt = updates.completedAt ?? new Date();
96	    if (!parsed.data.status) updates.status = "completed";
97	  } else if (parsed.data.completed === false) {
98	    updates.completedAt = null;
99	    if (!parsed.data.status || parsed.data.status === "completed") {
100	      updates.status = existing[0].status === "completed" ? "todo" : existing[0].status;
101	    }
102	  }
103	
104	  // If status is explicitly set to "completed", mark completed = true
105	  if (parsed.data.status === "completed" && parsed.data.completed !== false) {
106	    updates.completed = true;
107	    if (!updates.completedAt) updates.completedAt = existing[0].completedAt ?? new Date();
108	  }
109	
110	  // If status is explicitly set to a non-completed status, mark completed = false
111	  if (parsed.data.status && parsed.data.status !== "completed" && parsed.data.completed !== true) {
112	    updates.completed = false;
113	    updates.completedAt = null;
114	  }
115	
116	  const [updated] = await db.update(officeTasksTable)
117	    .set(updates)
118	    .where(eq(officeTasksTable.id, params.data.taskId))
119	    .returning();
120	
121	  res.json(updated);
122	});
